S=$0;read Q;read T;read K||K=0;K=${K:-0};python3 -c 'import sys,json,os;q=sys.argv[1];T=max(1,int(sys.argv[2]));k=sys.argv[3];S=sys.argv[4];J=lambda x:json.dumps(x,separators=(",",":"));C=lambda s:[w for w in("".join(c.lower()if c.isalnum()else" "for c in s).split())if w];R=C(q);W=R or["void"];qn=" ".join(R);tag="ontology";G=sum((b+1)*257**i for i,b in enumerate(J([qn,T,k,tag]).encode()));KV=sum((i+1)*(b+1)for i,b in enumerate(k.encode()));SR=sum((i+1)*(b+1)for i,b in enumerate(open(S,"rb").read()if os.path.exists(S)else b""))%10**18;b=min(T,12);N=(1<<(b+1))-1;M=997+G%97;F=lambda j:(G+SR*j+j*j+KV)%M;O=min((F(j),j)for j in range(N));ttl="Self-Origin %s V%s"%(W[0].title(),k);cl="s=1/2+i%d"%(G%1000000);V=int(len(R)>0 and qn==" ".join(R)and O==min((F(j),j)for j in range(N))and ttl=="Self-Origin %s V%s"%(W[0].title(),k));D={"P":"RMZ-ANSELM-ONTO-NOSHA","UTL":"RMZ-UTL/1","NL":"RMZ-NL/1","MATH":"RMZ-MATH/1","MML":"RMZ-MML/1","Q_RAW":q,"Q_NORM":qn,"TOKENS":R,"LANG":"en"if q.isascii()else"mixed","INTENT":tag,"AX":"Normalize;Encode;Compile;Verify","GRAM":"NL MATH MML SELF ORIGIN D0 CERT","VM":"qNL>qMath>qMML>qVerify>qHalt","VERIFY":"recalc NL/G/SELF/OPT/TITLE","REJECT":"V=0","SELF":SR,"ORIGIN":SR,"DELTA":0,"D0":1,"VARIANT":k,"SALT":KV,"BND":b,"ENUM":N,"G":str(G),"CL":cl,"OPT":O,"TITLE":ttl,"TT":"z0;NL;TZC;NZO;MATH;MML;certC","Ont":"Natural>Mathematical>Machine>Verify>Cert","V":V,"PCC":V,"ZE":V,"Bd":"bounded unified TM language; no full NL/RH"};open("ONR.clcert","w").write(J(D)+"\n");print(J({"P":D["P"],"TITLE":ttl,"UTL":D["UTL"],"V":V,"PCC":V,"ZE":V,"cert":"ONR.clcert","bytes":"<2048"}))' "$Q" "$T" "$K" "$S"